"use client"

// @dthu/ui 0.2.0 · block-auth
import * as React from "react"
import { KeyRound, LogOut, Moon, ShieldCheck, Sun, User } from "lucide-react"
import { ConfirmDialog } from "@/components/ui/alert-dialog"
import { DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator } from "@/components/ui/dropdown-menu"

export interface AccountMenuItemsProps {
  /** Heading of the menu (user's display name). */
  name: string
  onProfile?: () => void
  /** "Bảo mật tài khoản" (password, 2FA, devices). */
  onSecurity?: () => void
  onChangePassword?: () => void
  /** Show the theme switch. */
  dark?: boolean
  onToggleTheme?: () => void
  /** Called when "Đăng xuất" is chosen; omit to hide the item. Open a `SignOutDialog` here: it must live outside the menu, which unmounts on close. */
  onSignOut?: () => void
  /** Extra items placed before the separator (e.g. "Quay lại trang tài liệu"). */
  children?: React.ReactNode
}

/**
 * Content for `AppShell` / `AppLayout`'s `userMenu`: profile, security, change password, theme and "Đăng xuất".
 * Pair it with `SignOutDialog` (state kept by the host) to confirm before ending the session.
 */
export function AccountMenuItems({ name, onProfile, onSecurity, onChangePassword, dark, onToggleTheme, onSignOut, children }: AccountMenuItemsProps) {
  return (
    <>
      <DropdownMenuLabel>{name}</DropdownMenuLabel>
      {onProfile && <DropdownMenuItem onSelect={onProfile}><User />Thông tin cá nhân</DropdownMenuItem>}
      {onSecurity && <DropdownMenuItem onSelect={onSecurity}><ShieldCheck />Bảo mật tài khoản</DropdownMenuItem>}
      {onChangePassword && <DropdownMenuItem onSelect={onChangePassword}><KeyRound />Đổi mật khẩu</DropdownMenuItem>}
      {onToggleTheme && <DropdownMenuItem onSelect={onToggleTheme}>{dark ? <Sun /> : <Moon />}{dark ? "Giao diện sáng" : "Giao diện tối"}</DropdownMenuItem>}
      {children}
      {onSignOut && (
        <>
          <DropdownMenuSeparator />
          <DropdownMenuItem variant="destructive" onSelect={onSignOut}><LogOut />Đăng xuất</DropdownMenuItem>
        </>
      )}
    </>
  )
}

export interface SignOutDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onConfirm: () => void | Promise<unknown>
  /** Warn that unsaved work is lost. */
  unsavedChanges?: boolean
}

/** "Đăng xuất khỏi hệ thống?" confirmation. The confirm button shows a spinner while `onConfirm` is pending. */
export function SignOutDialog({ open, onOpenChange, onConfirm, unsavedChanges }: SignOutDialogProps) {
  return <ConfirmDialog open={open} onOpenChange={onOpenChange} title="Đăng xuất khỏi hệ thống?" description={unsavedChanges ? "Bạn còn thay đổi chưa lưu, chúng sẽ bị mất nếu đăng xuất." : "Phiên làm việc trên thiết bị này sẽ kết thúc."} confirmLabel="Đăng xuất" variant={unsavedChanges ? "destructive" : "default"} onConfirm={onConfirm} />
}

import * as React from "react"
import { Lock, ShieldAlert } from "lucide-react"
import { AuthError, AuthField, AuthLayout, AuthLink, AuthSubmit, PasswordStrength, defaultPasswordRules, evaluatePassword, type AuthBrandProps, type PasswordRule } from "./parts"

export interface ChangePasswordValues { current: string; password: string }
export interface ChangePasswordFormProps {
  rules?: PasswordRule[]
  submitting?: boolean
  error?: string
  submitLabel?: string
  className?: string
  onSubmit?: (v: ChangePasswordValues) => void
}

/** The three fields of "Đổi mật khẩu" (current, new, confirm) with live strength. Embed it in a dialog, a settings card or `ChangePasswordPage`. */
export function ChangePasswordForm({ rules = defaultPasswordRules, submitting, error, submitLabel = "Đổi mật khẩu", className, onSubmit }: ChangePasswordFormProps) {
  const [current, setCurrent] = React.useState("")
  const [password, setPassword] = React.useState("")
  const [confirm, setConfirm] = React.useState("")
  const [touched, setTouched] = React.useState(false)
  const ok = evaluatePassword(password, rules).valid
  const currentErr = touched && !current ? "Vui lòng nhập mật khẩu hiện tại" : undefined
  const passErr = touched && !currentErr && !ok ? "Mật khẩu chưa đạt đủ yêu cầu bên dưới" : touched && password && password === current ? "Mật khẩu mới phải khác mật khẩu hiện tại" : undefined
  const confirmErr = touched && confirm !== password ? "Mật khẩu nhập lại không khớp" : undefined
  return (
    <form noValidate className={className ?? "grid gap-[15px]"} onSubmit={(e) => { e.preventDefault(); setTouched(true); if (!current || !ok || password === current || confirm !== password) return; onSubmit?.({ current, password }) }}>
      <AuthError>{error}</AuthError>
      <AuthField id="chpw-current" type="password" label="Mật khẩu hiện tại" icon={<Lock />} autoComplete="current-password" value={current} onChange={(e) => setCurrent(e.target.value)} error={currentErr} />
      <AuthField id="chpw-new" type="password" label="Mật khẩu mới" icon={<Lock />} autoComplete="new-password" value={password} onChange={(e) => setPassword(e.target.value)} error={passErr} />
      <PasswordStrength password={password} rules={rules} />
      <AuthField id="chpw-confirm" type="password" label="Nhập lại mật khẩu mới" icon={<Lock />} autoComplete="new-password" value={confirm} onChange={(e) => setConfirm(e.target.value)} error={confirmErr} />
      <AuthSubmit disabled={submitting}>{submitting ? "Đang lưu..." : submitLabel}</AuthSubmit>
    </form>
  )
}

export interface ChangePasswordPageProps extends AuthBrandProps, Omit<ChangePasswordFormProps, "className" | "submitLabel"> {
  /** Why the change is required. `first-login` and `expired` cannot be skipped; `reset` is after an administrator reset. */
  reason?: "first-login" | "expired" | "reset"
  username?: string
  onSignOut?: () => void
}

const reasonText = {
  "first-login": "Đây là lần đăng nhập đầu tiên. Hãy đổi mật khẩu được cấp để tiếp tục.",
  expired: "Mật khẩu của bạn đã hết hạn theo chính sách bảo mật. Hãy đặt mật khẩu mới để tiếp tục.",
  reset: "Quản trị viên đã đặt lại mật khẩu của bạn. Hãy đổi sang mật khẩu của riêng bạn để tiếp tục.",
} as const

/** Full-page "Đổi mật khẩu" that blocks the app until done: first login, expired password or administrator reset. */
export function ChangePasswordPage({ reason = "first-login", username, onSignOut, rules, submitting, error, onSubmit, ...brand }: ChangePasswordPageProps) {
  return (
    <AuthLayout {...brand} icon={<ShieldAlert />} tone="warning" title="Đổi mật khẩu bắt buộc" subtitle={<>{username ? <>Tài khoản <b className="font-semibold text-foreground">{username}</b>. </> : null}{reasonText[reason]}</>}>
      <div className="grid gap-[15px]">
        <ChangePasswordForm rules={rules} submitting={submitting} error={error} onSubmit={onSubmit} submitLabel="Đổi mật khẩu và tiếp tục" />
        {onSignOut && <div className="text-center"><AuthLink onClick={onSignOut}>Đăng xuất</AuthLink></div>}
      </div>
    </AuthLayout>
  )
}

"use client"

// @dthu/ui 0.2.0 · block-auth
import * as React from "react"
import { ArrowLeft, KeyRound, MailCheck, User } from "lucide-react"
import { AuthError, AuthField, AuthLayout, AuthLink, AuthSubmit, useCountdown, type AuthBrandProps } from "./parts"

export interface ForgotPasswordPageProps extends AuthBrandProps {
  /** Label of the field. Default "Tài khoản hoặc email". */
  identifierLabel?: string
  submitting?: boolean
  error?: string
  /** Show the "link sent" state. Leave undefined to let the page switch itself after `onSubmit` returns. */
  sent?: boolean
  /** Seconds before "Gửi lại" is enabled. Default 60. */
  resendAfter?: number
  /** Called with the trimmed account or email. May be async; a rejection keeps the form and shows nothing, so set `error` yourself. */
  onSubmit?: (identifier: string) => void | Promise<void>
  onResend?: (identifier: string) => void | Promise<void>
  onBack?: () => void
  /** "Không nhận được thư?" support link. */
  onSupport?: () => void
}

/**
 * Forgot-password screen: asks for the account or email, then confirms that a reset link was sent (with a resend cool-down).
 * The confirmation never says whether the account exists, so the page cannot be used to probe for accounts.
 */
export function ForgotPasswordPage({ identifierLabel = "Tài khoản hoặc email", submitting, error, sent, resendAfter = 60, onSubmit, onResend, onBack, onSupport, ...brand }: ForgotPasswordPageProps) {
  const [identifier, setIdentifier] = React.useState("")
  const [touched, setTouched] = React.useState(false)
  const [localSent, setLocalSent] = React.useState(false)
  const [left, restart] = useCountdown(resendAfter, false)
  const done = sent ?? localSent
  const err = touched && !identifier.trim() ? "Vui lòng nhập tài khoản hoặc email" : undefined

  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    setTouched(true)
    if (!identifier.trim()) return
    try {
      await onSubmit?.(identifier.trim())
      setLocalSent(true)
      restart(resendAfter)
    } catch { /* the caller reports the failure through `error` */ }
  }

  if (done) {
    return (
      <AuthLayout {...brand} icon={<MailCheck />} tone="success" title="Kiểm tra hộp thư" subtitle={<>Nếu <b className="font-semibold text-foreground">{identifier.trim() || "tài khoản"}</b> tồn tại trong hệ thống, chúng tôi đã gửi hướng dẫn đặt lại mật khẩu. Liên kết có hiệu lực trong thời gian ngắn.</>}>
        <div className="grid gap-3.5">
          <p className="m-0 text-body text-muted-foreground">Không thấy thư? Kiểm tra mục thư rác, hoặc gửi lại sau khi hết thời gian chờ.</p>
          <AuthSubmit type="button" variant="outline" disabled={left > 0 || submitting} onClick={async () => { await onResend?.(identifier.trim()); restart(resendAfter) }}>
            {left > 0 ? `Gửi lại sau ${left}s` : "Gửi lại liên kết"}
          </AuthSubmit>
          <div className="flex items-center justify-between gap-3">
            <AuthLink onClick={onBack} className="inline-flex items-center gap-1.5"><ArrowLeft aria-hidden className="size-4" />Quay lại đăng nhập</AuthLink>
            {onSupport && <AuthLink onClick={onSupport}>Cần hỗ trợ?</AuthLink>}
          </div>
        </div>
      </AuthLayout>
    )
  }

  return (
    <AuthLayout {...brand} icon={<KeyRound />} title="Quên mật khẩu" subtitle="Nhập tài khoản hoặc email, chúng tôi sẽ gửi liên kết để bạn đặt mật khẩu mới.">
      <form noValidate onSubmit={submit} className="grid gap-[15px]">
        <AuthError>{error}</AuthError>
        <AuthField id="forgot-identifier" label={identifierLabel} icon={<User />} autoComplete="username" placeholder="Nhập tài khoản hoặc email" value={identifier} onChange={(e) => setIdentifier(e.target.value)} error={err} />
        <AuthSubmit disabled={submitting}>{submitting ? "Đang gửi..." : "Gửi liên kết đặt lại"}</AuthSubmit>
        <div className="text-center"><AuthLink onClick={onBack} className="inline-flex items-center gap-1.5"><ArrowLeft aria-hidden className="size-4" />Quay lại đăng nhập</AuthLink></div>
      </form>
    </AuthLayout>
  )
}

import * as React from "react"
import { Lock } from "lucide-react"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { AuthError, AuthField, AuthLink, AuthSubmit } from "./parts"

export interface LockScreenPageProps {
  name: string
  username?: string
  initials?: string
  avatarSrc?: string
  /** Logo shown top-left. */
  brand?: React.ReactNode
  /** CSS `background-image` value behind the dimmed overlay. */
  backgroundImage?: string
  submitting?: boolean
  error?: string
  /** Called with the typed password; the app decides whether it unlocks. */
  onUnlock?: (password: string) => void
  /** "Đăng nhập bằng tài khoản khác". */
  onSignOut?: () => void
}

const pad = (n: number) => String(n).padStart(2, "0")

/** Screen lock: keeps the user's place in the app but hides it until the password is typed again. Shows a clock like a phone lock screen. */
export function LockScreenPage({ name, username, initials, avatarSrc, brand, backgroundImage, submitting, error, onUnlock, onSignOut }: LockScreenPageProps) {
  const [now, setNow] = React.useState(() => new Date())
  const [password, setPassword] = React.useState("")
  const [touched, setTouched] = React.useState(false)
  React.useEffect(() => { const t = setInterval(() => setNow(new Date()), 15_000); return () => clearInterval(t) }, [])
  const err = touched && !password ? "Vui lòng nhập mật khẩu" : undefined
  const date = new Intl.DateTimeFormat("vi-VN", { weekday: "long", day: "2-digit", month: "2-digit", year: "numeric" }).format(now)
  return (
    <main data-slot="lock-screen" className="relative grid h-full min-h-0 w-full grid-rows-[auto_1fr] overflow-y-auto bg-sidebar text-white" style={{ backgroundImage: [backgroundImage && "linear-gradient(rgba(7,13,22,.7),rgba(7,13,22,.7))", backgroundImage, "linear-gradient(155deg,var(--sidebar),var(--primary))"].filter(Boolean).join(","), backgroundSize: "cover", backgroundPosition: "center" }}>
      <header className="flex items-center justify-between px-8 py-6 max-sm:px-4">{brand ?? <span />}<span className="flex items-center gap-1.5 text-small text-white/70"><Lock aria-hidden className="size-3.5" />Màn hình đang khóa</span></header>
      <div className="grid content-center justify-items-center gap-6 px-4 pb-12">
        <div className="text-center">
          <time dateTime={now.toISOString()} className="block text-[64px] leading-none font-extrabold tracking-tight tabular-nums max-sm:text-[48px]">{pad(now.getHours())}:{pad(now.getMinutes())}</time>
          <p className="m-0 mt-2 text-lead text-white/75 capitalize">{date}</p>
        </div>
        <section aria-label="Mở khóa" className="w-full max-w-[360px] rounded-[14px] bg-background px-6 pt-6 pb-5 text-foreground shadow-[0_12px_26px_-8px_rgba(0,14,28,0.3),0_32px_64px_-24px_rgba(0,14,28,0.34)]">
          <div className="mb-4 flex items-center gap-3">
            <Avatar className="size-12"><AvatarImage src={avatarSrc} alt="" /><AvatarFallback>{initials ?? name.split(" ").slice(-2).map((w) => w[0]).join("").toUpperCase()}</AvatarFallback></Avatar>
            <div className="min-w-0"><h1 className="m-0 truncate text-lead font-bold">{name}</h1>{username && <p className="m-0 truncate text-small text-muted-foreground">{username}</p>}</div>
          </div>
          <form noValidate onSubmit={(e) => { e.preventDefault(); setTouched(true); if (password) onUnlock?.(password) }} className="grid gap-3.5">
            <AuthError>{error}</AuthError>
            <AuthField id="lock-password" type="password" label="Mật khẩu" icon={<Lock />} autoComplete="current-password" autoFocus placeholder="Nhập mật khẩu để mở khóa" value={password} onChange={(e) => setPassword(e.target.value)} error={err} />
            <AuthSubmit disabled={submitting}>{submitting ? "Đang mở khóa..." : "Mở khóa"}</AuthSubmit>
            {onSignOut && <div className="text-center"><AuthLink onClick={onSignOut}>Đăng nhập bằng tài khoản khác</AuthLink></div>}
          </form>
        </section>
      </div>
    </main>
  )
}

"use client"

// @dthu/ui 0.2.0 · block-auth
import * as React from "react"
import { ArrowLeft, Smartphone } from "lucide-react"
import { InputOTP, InputOTPGroup, InputOTPSlot } from "@/components/ui/input-otp"
import { AuthError, AuthLayout, AuthLink, AuthSubmit, useCountdown, type AuthBrandProps } from "./parts"

export interface OtpVerifyPageProps extends AuthBrandProps {
  /** Where the code comes from. `app` = authenticator app (no resend). */
  method?: "app" | "sms" | "email"
  /** Masked destination, e.g. "0912 *** 789" or "a***@acme.vn". */
  target?: string
  /** Number of digits. Default 6. */
  length?: number
  submitting?: boolean
  error?: string
  /** Seconds before "Gửi lại mã" is enabled (sms / email). Default 30. */
  resendAfter?: number
  /** Offer a "tin tưởng thiết bị này" checkbox; its value is passed to `onSubmit`. */
  allowTrustDevice?: boolean
  /** Called when all digits are entered (automatically) or the button is pressed. */
  onSubmit?: (v: { code: string; trustDevice: boolean }) => void
  onResend?: () => void
  onUseAnotherMethod?: () => void
  onBack?: () => void
}

const methodText = {
  app: (t?: string) => `Mở ứng dụng xác thực${t ? ` (${t})` : ""} và nhập mã gồm {n} chữ số.`,
  sms: (t?: string) => `Chúng tôi đã gửi mã {n} chữ số qua tin nhắn tới ${t ?? "số điện thoại của bạn"}.`,
  email: (t?: string) => `Chúng tôi đã gửi mã {n} chữ số tới ${t ?? "email của bạn"}.`,
} as const

/** Second step of two-factor sign-in: digit boxes that submit on the last digit, resend cool-down, "use another method" and trusted-device option. */
export function OtpVerifyPage({ method = "app", target, length = 6, submitting, error, resendAfter = 30, allowTrustDevice, onSubmit, onResend, onUseAnotherMethod, onBack, ...brand }: OtpVerifyPageProps) {
  const [code, setCode] = React.useState("")
  const [trust, setTrust] = React.useState(false)
  const [left, restart] = useCountdown(resendAfter, method !== "app")
  const submit = (c: string) => { if (c.length === length) onSubmit?.({ code: c, trustDevice: trust }) }
  return (
    <AuthLayout {...brand} icon={<Smartphone />} title="Xác thực hai bước" subtitle={methodText[method](target).replace("{n}", String(length))}>
      <form noValidate onSubmit={(e) => { e.preventDefault(); submit(code) }} className="grid gap-[15px]">
        <AuthError>{error}</AuthError>
        <div>
          <label htmlFor="otp-code" className="mb-2 block text-body font-semibold text-foreground">Mã xác thực</label>
          <InputOTP id="otp-code" maxLength={length} value={code} onChange={setCode} onComplete={submit} inputMode="numeric" autoComplete="one-time-code" aria-invalid={error ? true : undefined} disabled={submitting} containerClassName="justify-between">
            <InputOTPGroup className="w-full justify-between gap-1.5 *:data-[slot=input-otp-slot]:h-12 *:data-[slot=input-otp-slot]:flex-1 *:data-[slot=input-otp-slot]:rounded-md *:data-[slot=input-otp-slot]:border">
              {Array.from({ length }, (_, i) => <InputOTPSlot key={i} index={i} />)}
            </InputOTPGroup>
          </InputOTP>
        </div>
        {allowTrustDevice && <label className="m-0 flex cursor-pointer items-center gap-2 text-control text-muted-foreground"><input type="checkbox" checked={trust} onChange={(e) => setTrust(e.target.checked)} className="m-0 size-4 accent-primary" />Tin tưởng thiết bị này trong 30 ngày</label>}
        <AuthSubmit disabled={submitting || code.length < length}>{submitting ? "Đang xác thực..." : "Xác nhận"}</AuthSubmit>
        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2 text-body">
          {method !== "app" ? <AuthLink disabled={left > 0} onClick={() => { onResend?.(); restart(resendAfter) }}>{left > 0 ? `Gửi lại mã sau ${left}s` : "Gửi lại mã"}</AuthLink> : <span />}
          {onUseAnotherMethod && <AuthLink onClick={onUseAnotherMethod}>Dùng cách khác</AuthLink>}
        </div>
        {onBack && <div className="text-center"><AuthLink onClick={onBack} className="inline-flex items-center gap-1.5"><ArrowLeft aria-hidden className="size-4" />Quay lại đăng nhập</AuthLink></div>}
      </form>
    </AuthLayout>
  )
}

import * as React from "react"
import { Check, Circle, Eye, EyeOff } from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Progress } from "@/components/ui/progress"
import { useCountdown } from "@/lib/use-countdown"

export { useCountdown }

/** Branding shared by every full-page auth screen; same props as `LoginPage` so one object themes the whole flow. */
export interface AuthBrandProps {
  /** Logo block above the form title. */
  brand?: React.ReactNode
  /** Headline of the brand panel. Without it the page is a single centred card (no side panel). */
  headline?: React.ReactNode
  /** Small uppercase organisation line above the headline. */
  org?: string
  /** Paragraph under the headline. */
  description?: string
  /** Bullet list of the brand panel. */
  features?: { icon?: React.ReactNode; title: string }[]
  /** Footer line (bottom-left of the brand panel, under the card on phones). */
  footer?: string
  /** CSS `background-image` value put under the brand panel's blue wash. */
  backgroundImage?: string
}

export interface AuthLayoutProps extends AuthBrandProps {
  /** Round icon above the title (status of the screen: key, mail, lock...). */
  icon?: React.ReactNode
  title: React.ReactNode
  subtitle?: React.ReactNode
  /** Tone of the icon bubble. */
  tone?: "primary" | "success" | "warning" | "destructive"
  children?: React.ReactNode
  className?: string
}

const wash = "linear-gradient(90deg,rgba(7,13,22,.62) 0%,rgba(7,13,22,.18) 62%,rgba(0,0,0,0) 100%),linear-gradient(155deg,rgba(13,23,38,.86) 0%,rgba(16,48,84,.7) 54%,rgba(0,73,152,.52) 100%)"
/** Split layout: the form is a plain column on desktop and becomes a card once the brand panel is hidden. (Literal class strings: Tailwind cannot see composed ones.) */
const cardOnPhone = "max-lg:max-w-[424px] max-lg:rounded-[14px] max-lg:bg-background max-lg:px-[30px] max-lg:pt-8 max-lg:pb-[26px] max-lg:shadow-[0_1px_2px_rgba(0,14,28,0.1),0_12px_26px_-8px_rgba(0,14,28,0.3),0_32px_64px_-24px_rgba(0,14,28,0.34)] max-sm:px-[22px] max-sm:pt-[26px] max-sm:pb-[22px]"
const cardAlways = "max-w-[424px] rounded-[14px] bg-background px-[30px] pt-8 pb-[26px] shadow-[0_1px_2px_rgba(0,14,28,0.1),0_12px_26px_-8px_rgba(0,14,28,0.3),0_32px_64px_-24px_rgba(0,14,28,0.34)] max-sm:px-[22px] max-sm:pt-[26px] max-sm:pb-[22px]"
const toneBubble ={ primary: "bg-accent text-primary", success: "bg-success/15 text-success", warning: "bg-warning/15 text-warning", destructive: "bg-destructive/10 text-destructive" } as const

/**
 * Frame of the screens around login: forgot / reset password, OTP, signed out, lock screen.
 * With `headline` it is the split layout of `LoginPage` (brand panel + 384px form column); without it a single card on the sidebar blue.
 * At <= 1023px the panel is hidden and the form sits on a card.
 */
export function AuthLayout({ brand, headline, org, description, features, footer, backgroundImage, icon, tone = "primary", title, subtitle, children, className }: AuthLayoutProps) {
  const split = headline != null
  return (
    <main data-slot="auth-layout" className={cn("relative grid h-full min-h-0 w-full overflow-y-auto bg-background text-foreground", split ? "grid-cols-[1.02fr_0.98fr] max-lg:grid-cols-1 max-lg:bg-sidebar" : "bg-sidebar", className)}>
      {split && (
